"""Offline evaluation view; full workbook galleries remain linked, not duplicated."""
import csv,html,json
from pathlib import Path
import common as C
from analysis import summarize
STYLE='''*{box-sizing:border-box}body{margin:0;background:#f3f6f9;color:#1b3046;font:15px/1.55 system-ui,sans-serif}header{background:#132c43;color:white;padding:36px max(24px,calc((100vw - 1360px)/2))}header p{color:#c6d5e3}h1{font-size:32px;line-height:1.2;margin:8px 0}main{max-width:1360px;margin:auto;padding:24px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;border:1px solid #dce4ec;border-radius:12px;padding:24px;margin:16px 0}nav{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 20px}a{color:#126c91;text-decoration:none}a:hover{text-decoration:underline}.button{padding:10px 14px;background:white;border:1px solid #dce4ec;border-radius:7px}.table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:10px 12px;border-bottom:1px solid #dce4ec;text-align:left;vertical-align:top}th{font-size:12px;text-transform:uppercase;color:#536a7f;background:#f7f9fb}.metric{font-size:27px;font-weight:650;display:block}.note,small{color:#5c7184}small{display:block}code{background:#edf2f7;padding:2px 5px;border-radius:4px}.badge{font-size:12px;padding:3px 7px;border-radius:4px;background:#edf2f7}.complete{color:#165e40;background:#e3f2e9}.failed,.timeout,.interrupted{color:#92281b;background:#fde9e3}details summary{cursor:pointer;font-weight:600}input{padding:10px;width:min(650px,100%);border:1px solid #cfdbe4;border-radius:7px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.15em;color:#96cbe7}@media(max-width:780px){.grid{grid-template-columns:1fr}main{padding:12px}}'''
def esc(v):return html.escape(str(v),quote=True)
def fmt(v):return '—' if v is None else f'{v:.2f}'
def render(root,state):
    s=summarize(state);C.atomic_json(root/'summary.json',s);sections=[]
    for g in s['groups']:
        rows=''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in (r['block'],r['variant'],f"{r['complete']}/{r['planned']}",r['repeat_pixels'],fmt(r['median_seconds']),fmt(r['min_seconds'])+'–'+fmt(r['max_seconds']),r['recovered']))+'</tr>' for r in g['rows'])
        choice=('<p>Policy selection: <strong>'+esc(g['selected'])+'</strong>; fastest eligible: '+esc(g['fastest'])+'.</p>') if g['selected'] else '<p class="note">See complete-scope and repeatability conditions in structured results. No selection is inferred from missing or conflicting data.</p>'
        sections.append('<section class="card" id="'+esc(g['id'])+'"><h2>'+esc(g['id'])+'</h2><p>'+esc(g['description'])+'</p>'+choice+'<div class="table"><table><thead><tr><th>Scope</th><th>Variant</th><th>Complete</th><th>Repeat pixels</th><th>Median s</th><th>Range s</th><th>Recovery</th></tr></thead><tbody>'+rows+'</tbody></table></div></section>')
    rows=[]
    for j in state['jobs']:
        c=j['candidate'];ms=(j.get('metrics')or{}).get('workload_ms');link='<a href="'+esc(j['report'])+'">Workbook report</a>' if j.get('report')else 'Not started'
        rows.append('<tr><td>'+esc(j['sequence'])+'</td><td>'+esc(j['stage'])+'</td><td>'+esc(Path(j['workbook']).name)+'<small>'+esc(', '.join(c.get('sheet_names') or ['Declared workbook scope']))+'</small></td><td>'+esc(c.get('comparison_variant',c['label']))+'</td><td><span class="badge '+esc(j['status'])+'">'+esc(j['status'])+'</span><small>'+esc(j.get('error') or '')+'</small></td><td>'+fmt(ms/1000 if ms is not None else None)+'</td><td>'+link+'</td></tr>')
    bundle='<a class="button" href="review-metadata.zip">Review bundle · no images</a>' if C.read_json(root/'bundle-status.json',{}).get('status')=='ready' else '<span class="button note">Review bundle pending</span>'
    issue_rows=''.join('<tr><td>'+esc(x['workbook'])+'</td><td>'+esc(str(x['sheet_index'])+' · '+json.dumps(x['sheet'],ensure_ascii=False))+'</td><td>'+esc(x['code'])+'</td><td>'+str(len(x['cases']))+'</td><td>'+''.join('<a href="cases/'+esc(c)+'/report.html">'+esc(c)+'</a><br>' for c in x['cases'])+'</td></tr>' for x in s['worksheet_issues'])
    issues=('<section class="card" id="worksheet-issues"><h2>Unresolved worksheet outcomes</h2><p>Repeated failures are grouped by exact workbook and sheet. They remain failures, not successful timing samples.</p><div class="table"><table><tr><th>Workbook</th><th>Sheet</th><th>Code</th><th>Cases</th><th>Evidence</th></tr>'+issue_rows+'</table></div></section>') if issue_rows else ''
    title='Capture evaluation' if s['mode']=='suite' else 'Individual experiment'
    doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' · Excel Shrink</title><style>'+STYLE+'</style></head><body><header><div class="eyebrow">Excel Shrink · Visual validation</div><h1>'+title+'</h1><p>'+esc(s['run_id'])+' · '+esc(s['status'])+'</p></header><main><nav>'+bundle+'<a class="button" href="summary.json">Structured results</a><a class="button" href="case-results.csv">Measurements CSV</a><a class="button" href="resolved-plan.json">Exact plan</a><a class="button" href="../../index.html">Run history</a></nav><div class="grid">'+''.join('<div class="card"><span class="metric">'+str(n)+'</span>'+esc(label)+'</div>' for label,n in [('Cases',len(state['jobs'])),('Complete',sum(j['status']=='complete' for j in state['jobs'])),('Inputs',len(state['files']))])+'</div><p>'+esc(s['scope'])+'</p><p class="note">'+esc(s['timing_note'])+'</p>'+issues+''.join(sections)+'<section class="card"><h2>Execution ledger</h2><input id="search" placeholder="Filter workbook, worksheet, variant or status" aria-label="Filter cases"><div class="table"><table id="jobs"><thead><tr><th>#</th><th>Group</th><th>Scope</th><th>Variant</th><th>Outcome</th><th>Workload s</th><th>Evidence</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></section><details class="card"><summary>Provenance and interpretation</summary><p><a href="source-manifest.json">Source hashes</a> and the exact plan record input SHA-256, worksheet names, settings and order. Different environments, incomplete scopes or inconsistent pixels are not equivalent results. Agreement between implementations is not an independent visual oracle.</p></details></main><script>document.getElementById("search").addEventListener("input",function(){var q=this.value.toLowerCase();document.querySelectorAll("#jobs tbody tr").forEach(function(r){r.hidden=!r.textContent.toLowerCase().includes(q);});});</script></body></html>'
    (root/'report.html').write_text(doc,encoding='utf-8')
    data=s['runs']+s['recoveries'];fields=list(data[0]) if data else ['case_id','status']
    with (root/'case-results.csv').open('w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
        for row in data:w.writerow(dict(row,sheets=json.dumps(row['sheets'],ensure_ascii=False)))
    meta=C.read_json(root/'run.json',{})
    if meta:meta.update(status=state['status'],completed_utc=state.get('ended_utc'));C.atomic_json(root/'run.json',meta)
    C.atomic_json(root/'result.json',dict(schema='vv-run-result-v1',run=meta,status=state['status'],outputs=[{'path':x} for x in ['summary.json','case-results.csv','resolved-plan.json','evaluation-state.json']],errors=state.get('errors',[]),note=s['scope']))
